const lockTable = `-- name: LockTable :one
SELECT table_id, area_id, name, capacity, shape, is_active, released_at FROM tables
WHERE table_id = $1 AND outlet_id = $2 AND deleted_at IS NULL
FOR UPDATE
`

type LockTableParams struct {
	TableID  string
	OutletID string
}

type LockTableRow struct {
	TableID    string
	AreaID     string
	Name       string
	Capacity   *int32
	Shape      string
	IsActive   bool
	ReleasedAt *time.Time
}

// For a change, a release or a delete of the table. A sale at it takes it
// FOR SHARE, so it waits for these and they wait for the sale.
func (q *Queries) LockTable(ctx context.Context, arg LockTableParams) (LockTableRow, error) {
	row := q.db.QueryRow(ctx, lockTable, arg.TableID, arg.OutletID)
	var i LockTableRow
	err := row.Scan(
		&i.TableID,
		&i.AreaID,
		&i.Name,
		&i.Capacity,
		&i.Shape,
		&i.IsActive,
		&i.ReleasedAt,
	)
	return i, err
}

const nextAreaOrder = `-- name: NextAreaOrder :one
SELECT COALESCE(max(sort_order) + 1, 0)::integer FROM table_areas
WHERE outlet_id = $1 AND deleted_at IS NULL
`

// A new area goes last.
func (q *Queries) NextAreaOrder(ctx context.Context, outletID string) (int32, error) {
	row := q.db.QueryRow(ctx, nextAreaOrder, outletID)
	var column_1 int32
	err := row.Scan(&column_1)
	return column_1, err
}

const placeTables = `-- name: PlaceTables :exec
UPDATE tables t SET x = p.x, y = p.y, w = p.w, h = p.h, rotation = p.rotation, shape = p.shape, updated_at = now()
FROM (
    SELECT unnest($2::text[]) AS table_id, unnest($3::integer[]) AS x, unnest($4::integer[]) AS y,
        unnest($5::integer[]) AS w, unnest($6::integer[]) AS h, unnest($7::integer[]) AS rotation,
        unnest($8::text[]) AS shape
) AS p
WHERE t.table_id = p.table_id AND t.area_id = $1
    AND (t.x, t.y, t.w, t.h, t.rotation, t.shape) IS DISTINCT FROM (p.x, p.y, p.w, p.h, p.rotation, p.shape)
`

type PlaceTablesParams struct {
	AreaID    string
	TableIds  []string
	Xs        []int32
	Ys        []int32
	Ws        []int32
	Hs        []int32
	Rotations []int32
	Shapes    []string
}

// Puts each of the tables in its box, with its turn and shape; a table
// whose place didn't change isn't touched.
// The arrays are all as long, and zipped.
func (q *Queries) PlaceTables(ctx context.Context, arg PlaceTablesParams) error {
	_, err := q.db.Exec(ctx, placeTables,
		arg.AreaID,
		arg.TableIds,
		arg.Xs,
		arg.Ys,
		arg.Ws,
		arg.Hs,
		arg.Rotations,
		arg.Shapes,
	)
	return err
}

const releaseTable = `-- name: ReleaseTable :exec
UPDATE tables SET released_at = clock_timestamp(), updated_at = now()
WHERE table_id = $1
`

// Timed by clock_timestamp() under the table's lock, as a sale is, so the
// two compare in the order they happened.
func (q *Queries) ReleaseTable(ctx context.Context, tableID string) error {
	_, err := q.db.Exec(ctx, releaseTable, tableID)
	return err
}

