const updateTable = `-- name: UpdateTable :exec
UPDATE tables SET
    name = $1, capacity = $2, shape = $3,
    x = CASE WHEN area_id = $4 THEN x END,
    y = CASE WHEN area_id = $4 THEN y END,
    w = CASE WHEN area_id = $4 THEN w END,
    h = CASE WHEN area_id = $4 THEN h END,
    area_id = $4, updated_at = now()
WHERE table_id = $5
`

type UpdateTableParams struct {
	Name     string
	Capacity *int32
	Shape    string
	AreaID   string
	TableID  string
}

// A table that moves to another area leaves its place in the old one's
// layout.
func (q *Queries) UpdateTable(ctx context.Context, arg UpdateTableParams) error {
	_, err := q.db.Exec(ctx, updateTable,
		arg.Name,
		arg.Capacity,
		arg.Shape,
		arg.AreaID,
		arg.TableID,
	)
	return err
}
